#!/bin/bash
# Opens the Antakya case world (generated by tools/export-gazebo.mjs) in Gazebo Harmonic.
#   bash sim/run_antakya.sh            GUI with aerial start view
#   bash sim/run_antakya.sh --server   headless server only
set -e
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source /opt/ros/jazzy/setup.bash 2>/dev/null || true
export GZ_PARTITION="${GZ_PARTITION:-aegis_antakya}"
WORLD="$HERE/worlds/antakya_aoi_m1.sdf"
if [ "$1" = "--server" ]; then exec gz sim -s -r "$WORLD"; fi
exec gz sim -r --gui-config "$HERE/gui/antakya.config" "$WORLD"
